import re

def _normalize(s: str) -> str:
    s = (s or "").lower().replace(".", " ")
    return re.sub(r"\s+", " ", s).strip()


def resolve_case_name(variant: str):
    LEGAL_STARTERS = {
        "Section", "Article", "Under", "Whether", "When", "What",
        "How", "Where", "Which", "Can", "Is", "Are", "Does", "Order",
    }
    parts = variant.split()
    name_tokens = []
    for tok in parts:
        clean = tok.rstrip(".,")
        if clean in LEGAL_STARTERS or (clean and clean[0].isdigit()):
            break
        if clean and clean[0].isupper() and len(clean) >= 2:
            name_tokens.append(tok)
        else:
            break
    if not name_tokens:
        return None
    # Step 1: full extracted name
    full = _normalize(" ".join(name_tokens))
    if full in AUTHORITY_INDEX:
        return AUTHORITY_INDEX[full]
    # Step 2: progressively shorter prefixes (down to 2 tokens)
    for n in range(len(name_tokens) - 1, 1, -1):
        candidate = _normalize(" ".join(name_tokens[:n]))
        if candidate in AUTHORITY_INDEX:
            return AUTHORITY_INDEX[candidate]
    # Step 3: substring scan — does any alias start with our full name?
    # Catches "Anvar P.V." → "anvar p v v p k basheer"
    if full:
        prefix = full + " "
        for key in AUTHORITY_INDEX:
            if key.startswith(prefix):
                return AUTHORITY_INDEX[key]
    # Step 4: single-token fallback for known landmark single-word aliases
    if name_tokens:
        single = _normalize(name_tokens[0])
        if single in AUTHORITY_INDEX:
            return AUTHORITY_INDEX[single]
    return None